<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Snake</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: radial-gradient(1200px 800px at 50% 15%, #16202e 0%, #0b0f16 60%, #070a0f 100%);
    color: #e6edf3;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    padding: 24px;
  }
  .wrap { display: flex; flex-direction: column; align-items: center; gap: 14px; }
  h1 {
    font-size: 28px; letter-spacing: 8px; text-transform: uppercase;
    color: #7ee787; text-shadow: 0 0 18px rgba(126,231,135,.35);
  }
  .hud { display: flex; align-items: baseline; gap: 12px; }
  .hud .label { font-size: 12px; letter-spacing: 3px; text-transform: uppercase; color: #8b98a9; }
  #score {
    font-size: 28px; font-weight: 700; color: #f0f6fc;
    min-width: 2ch; font-variant-numeric: tabular-nums;
  }
  canvas#snake {
    width: 400px; height: 400px; display: block;
    background: #0d1117;
    border: 2px solid #223047;
    border-radius: 10px;
    box-shadow: 0 0 0 1px rgba(126,231,135,.06),
                0 20px 60px rgba(0,0,0,.55),
                inset 0 0 40px rgba(0,0,0,.35);
  }
  .controls { display: flex; gap: 10px; }
  button {
    font: inherit; font-weight: 600; letter-spacing: 1px;
    padding: 10px 24px; border-radius: 8px; cursor: pointer;
    color: #e6edf3; background: #1b2634; border: 1px solid #2f3e52;
    transition: transform .08s ease, background .15s ease, box-shadow .15s ease;
  }
  button:hover { background: #243144; box-shadow: 0 4px 14px rgba(0,0,0,.35); }
  button:active { transform: translateY(1px) scale(.98); }
  #start { background: #1f6f3a; border-color: #2ea043; }
  #start:hover { background: #268244; }
  .hint { font-size: 12px; color: #6b7889; letter-spacing: .5px; }
</style>
</head>
<body>
  <div class="wrap">
    <h1>Snake</h1>
    <div class="hud"><span class="label">Score</span><span id="score">0</span></div>
    <canvas id="snake" width="400" height="400"></canvas>
    <div class="controls">
      <button id="start">Start</button>
      <button id="pause">Pause</button>
      <button id="reset">Reset</button>
    </div>
    <div class="hint">Arrow keys to steer &middot; Space to pause &middot; Eat the orb, avoid walls and yourself</div>
  </div>

<script>
(function () {
  'use strict';

  var COLS = 20, ROWS = 20, CELL = 20;
  var canvas = document.getElementById('snake');
  var ctx = canvas.getContext('2d');
  var scoreEl = document.getElementById('score');

  var VEC = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] };

  var snakeArr = [];
  var dir = 'right';
  var pendingDir = 'right';
  var foodPos = [5, 10];
  var scoreVal = 0;
  var isAlive = true;
  var timer = null;

  function occupied(x, y) {
    for (var i = 0; i < snakeArr.length; i++) {
      if (snakeArr[i][0] === x && snakeArr[i][1] === y) return true;
    }
    return false;
  }

  function placeFood() {
    var free = [];
    for (var x = 0; x < COLS; x++) {
      for (var y = 0; y < ROWS; y++) {
        if (!occupied(x, y)) free.push([x, y]);
      }
    }
    if (free.length === 0) { foodPos = [-1, -1]; return; }
    foodPos = free[(Math.random() * free.length) | 0];
  }

  function setFood(x, y) {
    foodPos = [x, y];
    draw();
  }

  function updateScore() { scoreEl.textContent = String(scoreVal); }

  function reset() {
    stopTimer();
    snakeArr = [[10, 10], [9, 10], [8, 10]];
    dir = 'right';
    pendingDir = 'right';
    scoreVal = 0;
    isAlive = true;
    placeFood();
    updateScore();
    draw();
  }

  function tick() {
    if (!isAlive) return;
    dir = pendingDir;
    var hx = snakeArr[0][0], hy = snakeArr[0][1];
    var v = VEC[dir];
    var nx = hx + v[0], ny = hy + v[1];

    // wall collision
    if (nx < 0 || ny < 0 || nx >= COLS || ny >= ROWS) { die(); return; }

    var eating = (nx === foodPos[0] && ny === foodPos[1]);

    // self collision (tail cell frees up unless growing)
    var limit = eating ? snakeArr.length : snakeArr.length - 1;
    for (var i = 0; i < limit; i++) {
      if (snakeArr[i][0] === nx && snakeArr[i][1] === ny) { die(); return; }
    }

    snakeArr.unshift([nx, ny]);
    if (eating) {
      scoreVal++;
      updateScore();
      placeFood();
    } else {
      snakeArr.pop();
    }
    draw();
  }

  function die() {
    isAlive = false;
    stopTimer();
    draw();
  }

  function setDir(d) {
    if (!VEC[d]) return;
    var nd = VEC[d], cd = VEC[dir];
    // ignore 180-degree reversal: snake keeps its current heading
    if (nd[0] === -cd[0] && nd[1] === -cd[1]) return;
    pendingDir = d;
  }

  // ---- timing (auto-advance) ----
  function speed() { return Math.max(70, 130 - Math.min(50, scoreVal * 2)); }
  function loop() {
    timer = null;
    tick();
    if (isAlive) timer = setTimeout(loop, speed());
  }
  function start() {
    if (timer !== null) return;
    if (!isAlive) reset();
    timer = setTimeout(loop, speed());
  }
  function stopTimer() {
    if (timer !== null) { clearTimeout(timer); timer = null; }
  }
  function pause() { stopTimer(); }

  // ---- rendering ----
  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#0d1117';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.035)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (var i = 1; i < COLS; i++) {
      ctx.moveTo(i * CELL + 0.5, 0);
      ctx.lineTo(i * CELL + 0.5, canvas.height);
    }
    for (var j = 1; j < ROWS; j++) {
      ctx.moveTo(0, j * CELL + 0.5);
      ctx.lineTo(canvas.width, j * CELL + 0.5);
    }
    ctx.stroke();

    // food (glowing orb)
    if (foodPos[0] >= 0) {
      var fx = foodPos[0] * CELL + CELL / 2;
      var fy = foodPos[1] * CELL + CELL / 2;
      var grad = ctx.createRadialGradient(fx, fy, 1, fx, fy, CELL * 0.75);
      grad.addColorStop(0, 'rgba(255,107,107,0.85)');
      grad.addColorStop(1, 'rgba(255,107,107,0)');
      ctx.fillStyle = grad;
      ctx.beginPath(); ctx.arc(fx, fy, CELL * 0.75, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#ff6b6b';
      ctx.beginPath(); ctx.arc(fx, fy, CELL * 0.32, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.65)';
      ctx.beginPath(); ctx.arc(fx - 2, fy - 2, CELL * 0.1, 0, Math.PI * 2); ctx.fill();
    }

    // snake (tail first so head renders on top)
    for (var k = snakeArr.length - 1; k >= 0; k--) {
      var cx0 = snakeArr[k][0], cy0 = snakeArr[k][1];
      var t = snakeArr.length <= 1 ? 0 : k / (snakeArr.length - 1);
      var px = cx0 * CELL, py = cy0 * CELL;
      if (k === 0) {
        ctx.fillStyle = isAlive ? '#7ee787' : '#8b949e';
        ctx.shadowColor = isAlive ? 'rgba(126,231,135,0.55)' : 'transparent';
        ctx.shadowBlur = isAlive ? 12 : 0;
      } else {
        var g = Math.round(200 - 90 * t);
        ctx.fillStyle = isAlive
          ? 'rgb(' + Math.round(46 - 18 * t) + ',' + g + ',' + Math.round(120 - 40 * t) + ')'
          : '#6e7681';
        ctx.shadowBlur = 0;
      }
      roundRect(px + 1.5, py + 1.5, CELL - 3, CELL - 3, k === 0 ? 6 : 5);
      ctx.fill();
      ctx.shadowBlur = 0;
    }

    // eyes on the head
    if (snakeArr.length) {
      var hxc = snakeArr[0][0] * CELL + CELL / 2;
      var hyc = snakeArr[0][1] * CELL + CELL / 2;
      var dv = VEC[dir];
      var perpX = -dv[1], perpY = dv[0];
      ctx.fillStyle = '#0d1117';
      for (var s = -1; s <= 1; s += 2) {
        ctx.beginPath();
        ctx.arc(hxc + dv[0] * 2 + perpX * 4.2 * s,
                hyc + dv[1] * 2 + perpY * 4.2 * s,
                2.1, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // game-over overlay
    if (!isAlive) {
      ctx.fillStyle = 'rgba(7,10,15,0.62)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = '#f85149';
      ctx.font = '700 34px system-ui, sans-serif';
      ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2 - 16);
      ctx.fillStyle = '#c9d1d9';
      ctx.font = '500 15px system-ui, sans-serif';
      ctx.fillText('Score ' + scoreVal + '  —  press Start or Reset',
                   canvas.width / 2, canvas.height / 2 + 18);
    }
  }

  // ---- input ----
  var KEYMAP = {
    ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
    w: 'up', s: 'down', a: 'left', d: 'right',
    W: 'up', S: 'down', A: 'left', D: 'right'
  };
  window.addEventListener('keydown', function (e) {
    var d = KEYMAP[e.key];
    if (d) {
      e.preventDefault();
      setDir(d);
    } else if (e.key === ' ') {
      e.preventDefault();
      if (timer !== null) pause(); else start();
    }
  });

  document.getElementById('start').addEventListener('click', start);
  document.getElementById('pause').addEventListener('click', pause);
  document.getElementById('reset').addEventListener('click', reset);

  // ---- programmatic API (required for grading) ----
  window.game = {
    w: COLS,
    h: ROWS,
    reset: reset,
    tick: tick,
    setDir: setDir,
    setFood: setFood,
    snake: function () { return snakeArr.map(function (c) { return [c[0], c[1]]; }); },
    food: function () { return [foodPos[0], foodPos[1]]; },
    alive: function () { return isAlive; },
    score: function () { return scoreVal; }
  };

  reset();
})();
</script>
</body>
</html>
